def compute(vars):
    total_net_derivatives = vars["v1"]
    foreign_exchange_derivatives = vars["v2"]
    result = total_net_derivatives - foreign_exchange_derivatives

    return {
        "value": result,
        "trace": {
            "total_net_derivatives": total_net_derivatives,
            "foreign_exchange_derivatives": foreign_exchange_derivatives,
            "result": result,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
